const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const matter = require('gray-matter');

const app = express();

// ── Security: CORS — restrict to localhost origins ────────────────────────────
const ALLOWED_ORIGINS = new Set([
  'http://localhost:3847',
  'http://localhost:5173',   // Vite dev
  'http://localhost:3000',
  'http://localhost:8080',
  'http://127.0.0.1:3847',
  'http://127.0.0.1:5173',
  'http://127.0.0.1:3000',
  'http://127.0.0.1:8080',
]);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.has(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  } else if (!origin) {
    // Same-origin or server-to-server (no Origin header)
    res.header('Access-Control-Allow-Origin', '*');
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ── Security: Localhost-only guard ────────────────────────────────────────────
app.use((req, res, next) => {
  const ip = req.ip || req.connection?.remoteAddress || '';
  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
  if (!isLocal) {
    return res.status(403).json({ error: 'Claude Hub is local-only' });
  }
  next();
});

// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
const rateLimitMap = new Map();
const RATE_LIMIT_WINDOW = 60_000; // 1 minute
const RATE_LIMITS = {
  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
  write: 60,   // file writes, creates, deletes — 60/min
  read: 200,   // reads, listings — 200/min
};

function rateLimit(tier) {
  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
  return (req, res, next) => {
    const key = `${tier}:${req.ip}`;
    const now = Date.now();
    let entry = rateLimitMap.get(key);
    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
      entry = { start: now, count: 0 };
      rateLimitMap.set(key, entry);
    }
    entry.count++;
    if (entry.count > max) {
      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
    }
    next();
  };
}

// Cleanup stale entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of rateLimitMap) {
    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
  }
}, 300_000);

// ── Security: Helmet-like headers ────────────────────────────────────────────
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

app.use(express.json({ limit: '2mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');
const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
const HISTORY_PATH = path.join(__dirname, '..', 'chat-history.json');
const ORCHESTRATIONS_PATH = path.join(__dirname, '..', 'orchestrations.json');
const RUN_HISTORY_PATH = path.join(__dirname, '..', 'run-history.json');
const MEMORY_LOG_PATH = path.join(__dirname, '..', 'memory-audit-log.json');

// --- Security: Name & Path Validation ---
function isValidName(name) {
  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
}

function validateName(req, res, next) {
  if (!isValidName(req.params.name)) {
    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
  }
  next();
}

function resolveProjectPath(id) {
  try {
    const decoded = Buffer.from(id, 'base64url').toString();
    // Prevent path traversal: resolve and check for .. sequences
    const resolved = path.resolve(decoded);
    if (resolved.includes('..') || decoded.includes('\0')) return null;
    return resolved;
  } catch {
    return null;
  }
}

function validateProjectId(req, res, next) {
  const projectPath = resolveProjectPath(req.params.id);
  if (!projectPath) {
    return res.status(400).json({ error: 'Invalid project ID' });
  }
  // Verify it's within allowed project directories
  const config = loadConfig();
  const allowedRoots = [
    CLAUDE_DIR,
    ...config.projectDirs.map(d => path.resolve(d.replace(/^~/, HOME))),
  ];
  const isAllowed = allowedRoots.some(root =>
    projectPath === root || projectPath.startsWith(root + path.sep)
  );
  if (!isAllowed) {
    return res.status(403).json({ error: 'Project outside allowed directories' });
  }
  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
    return res.status(404).json({ error: 'Project directory not found' });
  }
  req.projectPath = projectPath;
  next();
}

// --- Config Management ---
function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      const raw = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
      // Validate structure
      if (!raw || typeof raw !== 'object') return { projectDirs: [] };
      if (!Array.isArray(raw.projectDirs)) raw.projectDirs = [];
      // Ensure all entries are strings
      raw.projectDirs = raw.projectDirs.filter(d => typeof d === 'string');
      return raw;
    }
  } catch {}
  return { projectDirs: [] };
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2));
}

// --- Helpers ---
function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function readFileSafe(filePath) {
  try {
    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
  } catch {}
  return null;
}

function parseAgent(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const { data, content: body } = matter(content);
    const stats = fs.statSync(filePath);
    return {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      body: body.trim(),
      raw: content,
      updatedAt: stats.mtime.toISOString(),
    };
  } catch (e) {
    return null;
  }
}

function listAgents(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgent(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

function listMdFiles(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const filePath = path.join(dir, f);
        const content = readFileSafe(filePath);
        const stats = fs.statSync(filePath);
        return {
          name: f.replace('.md', ''),
          content: content || '',
          path: filePath,
          updatedAt: stats.mtime.toISOString(),
        };
      });
  } catch {
    return [];
  }
}

// --- Rule Templates ---
const RULE_TEMPLATES = [
  {
    id: 'no-any',
    name: 'No Any Types',
    description: 'Forbid usage of TypeScript `any` type',
    category: 'typescript',
    content: `Never use the TypeScript \`any\` type. No exceptions.

Alternatives:
- Use specific types or interfaces
- Use generics for flexible typing
- Use \`unknown\` with type guards for truly unknown data
- Use \`Parameters<typeof fn>[0]\` to infer parameter types

Also forbidden: \`as any\`, \`@ts-ignore\`, \`@ts-expect-error\` (unless the comment explains exactly why and when it will be fixed).`,
  },
  {
    id: 'zod-validation',
    name: 'Zod Validation',
    description: 'Require Zod schemas for all API input validation',
    category: 'validation',
    content: `All API routes must validate request input with Zod schemas. Never trust raw request data.

Required pattern:
\`\`\`typescript
const schema = z.object({ ... })
const result = schema.safeParse(await request.json())
if (!result.success) return Response.json({ error: result.error.flatten() }, { status: 400 })
\`\`\`

Never access \`request.json()\` fields directly without validation.
Never use \`schema.parse()\` — always \`schema.safeParse()\` with explicit error handling.`,
  },
  {
    id: 'no-console-log',
    name: 'No Console.log',
    description: 'Use structured logging instead of console.log in production code',
    category: 'logging',
    content: `Never use \`console.log\`, \`console.warn\`, or \`console.error\` directly in production code.

- Use the project's structured logger instead
- Include contextual metadata (request ID, user ID, operation name)
- Use appropriate log levels (debug, info, warn, error)
- Exception: CLI scripts and build tooling may use console directly`,
  },
  {
    id: 'error-handling',
    name: 'Error Handling',
    description: 'Proper error handling patterns — no silent catches',
    category: 'reliability',
    content: `All errors must be caught, typed, and handled appropriately.

- Never swallow errors silently (empty catch blocks)
- Use custom error classes extending Error for domain errors
- Always include the original error as the cause
- Return Result types or throw — never return null to indicate failure
- Never expose raw database or third-party errors to the client`,
  },
  {
    id: 'no-hardcoded-secrets',
    name: 'No Hardcoded Secrets',
    description: 'Never hardcode credentials or API keys in source code',
    category: 'security',
    content: `Never hardcode API keys, passwords, tokens, or connection strings in source code.

- Use environment variables for all secrets
- Reference secrets from a .env file (never committed to git)
- Check .env.example matches actual .env keys
- Never log secrets or include them in error messages`,
  },
  {
    id: 'no-direct-push',
    name: 'No Direct Push to Main',
    description: 'Always use feature branches and pull requests',
    category: 'git',
    content: `Never commit or push directly to the main branch.

Always create a feature branch:
- Branch name format: feature/[short-description] or fix/[short-description]
- Example: git checkout -b feature/csv-import

Open a pull request for all changes. Never use git push origin main.`,
  },
  {
    id: 'no-mock-db',
    name: 'No Mock Database',
    description: 'Always use real test databases instead of mocks',
    category: 'testing',
    content: `Never mock the database in tests. Always use a real test database with seed data.

Never use: jest.mock('prisma'), vi.mock('@/lib/db'), or any database stub.
Always use: a dedicated test database with DATABASE_URL_TEST in .env.test.

Mocked DB tests give false confidence. Real DB tests catch actual query bugs.`,
  },
  {
    id: 'prisma-migrations',
    name: 'Prisma Migrations Only',
    description: 'All schema changes must go through Prisma migrations',
    category: 'database',
    content: `Never modify schema.prisma and apply changes manually in production.

All schema changes must go through:
1. Edit prisma/schema.prisma
2. Run: npx prisma migrate dev --name [descriptive-name]
3. Run: npx prisma generate
4. Commit both the schema change and the migration file

Never run npx prisma db push in production — use migrate deploy.
Never run npx prisma migrate reset without explicit user confirmation.`,
  },
];

function discoverProjects(dirs) {
  const projects = [];
  for (const dir of dirs) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
          projects.push({
            id: Buffer.from(projectPath).toString('base64url'),
            name: entry.name,
            path: projectPath,
            displayPath: projectPath.replace(HOME, '~'),
            hasClaudeDir,
            hasClaudeMd,
            agentCount: agents.length,
            commandCount: commands.length,
            ruleCount: rules.length,
            agents,
            commands: commands.map(c => c.name),
            rules: rules.map(r => r.name),
          });
        }
      }
    } catch {}
  }
  return projects;
}

// --- API Routes ---

// Config
app.get('/api/config', (req, res) => {
  const config = loadConfig();
  res.json({
    claudeDir: CLAUDE_DIR,
    claudeDirExists: fs.existsSync(CLAUDE_DIR),
