const TRAINING_DIR = path.join(CLAUDE_DIR, 'training');

function loadTraining(agentName) {
  const filePath = path.join(TRAINING_DIR, agentName + '.json');
  try {
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    }
  } catch {}
  return [];
}

function saveTraining(agentName, data) {
  ensureDir(TRAINING_DIR);
  fs.writeFileSync(path.join(TRAINING_DIR, agentName + '.json'), JSON.stringify(data, null, 2));
