import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  ShieldCheck,
  Search,
  FolderOpen,
  Clock,
  ChevronDown,
  ChevronRight,
  Plus,
  Trash2,
  Pencil,
  X,
  Globe,
  BookTemplate,
  Zap,
  Filter,
} from 'lucide-react'
import {
  getUnifiedRules,
  deleteProjectRule,
  deleteGlobalRule,
  updateProjectRule,
  updateGlobalRule,
  sanitizeName,
  getRuleTemplates,
  applyRuleTemplateGlobal,
  applyRuleTemplateProject,
  initAllRules,
} from '../lib/api'
import { getProjects } from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedRule } from '../types'
import type { RuleTemplate } from '../lib/api'
import { toast } from '../components/Toast'

type ScopeFilter = 'all' | 'global' | 'project'

export default function AllRules() {
  const { data: rules, loading, refetch } = useApi(getUnifiedRules)
  const { data: projects } = useApi(getProjects)
  const { data: templates } = useApi(getRuleTemplates)
  const navigate = useNavigate()
  const [search, setSearch] = useState('')
  const [expanded, setExpanded] = useState<string | null>(null)
  const [scopeFilter, setScopeFilter] = useState<ScopeFilter>('all')
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [creating, setCreating] = useState(false)
  const [createLoading, setCreateLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [createScope, setCreateScope] = useState<string>('global')
  const [deletingKeys, setDeletingKeys] = useState<Set<string>>(new Set())
  const [showTemplates, setShowTemplates] = useState(false)
  const [templateScope, setTemplateScope] = useState<string>('global')
  const [applyingTemplate, setApplyingTemplate] = useState<string | null>(null)
  const [initializing, setInitializing] = useState(false)

  // Filter rules
  const filtered = (rules || []).filter((r) => {
    if (search && !r.name.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && r.scope !== 'global') return false
    if (scopeFilter === 'project' && r.scope !== 'project') return false
    if (projectFilter !== 'all' && r.scope === 'project' && r.projectId !== projectFilter) return false
    return true
  })

  // Separate global and project rules
  const globalRules = filtered.filter(r => r.scope === 'global')
  const projectRules = filtered.filter(r => r.scope === 'project')

  // Group project rules by project
  const projectGroups = new Map<string, UnifiedRule[]>()
  for (const rule of projectRules) {
    const key = rule.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(rule)
  }

  const uniqueProjects = [
    ...new Map(
      (rules || [])
        .filter(r => r.scope === 'project' && r.projectId)
        .map(r => [r.projectId!, { id: r.projectId!, name: r.projectName! }])
    ).values(),
  ]

  const allProjects = projects || []

  // Count projects without rules directories
  const projectsWithoutRules = allProjects.filter(p => p.ruleCount === 0)

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = sanitizeName(newName)
    if (!slug) {
      toast('error', 'Invalid name \u2014 use letters, numbers, or hyphens')
      return
    }
    setCreateLoading(true)
    try {
      const template = `Describe the rule Claude must follow.`
      if (createScope === 'global') {
        await updateGlobalRule(slug, template)
        setCreating(false)
        setNewName('')
        navigate(`/global/rules/${slug}`)
      } else {
        await updateProjectRule(createScope, slug, template)
        setCreating(false)
        setNewName('')
        navigate(`/projects/${createScope}/rules/${slug}`)
      }
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create rule')
    } finally {
      setCreateLoading(false)
    }
  }

  const handleDelete = async (rule: UnifiedRule) => {
    const label = rule.scope === 'global' ? 'global rules' : rule.projectName
    if (!confirm(`Delete rule "${rule.name}" from ${label}?`)) return
    const key = `${rule.scope}-${rule.projectId}-${rule.name}`
    setDeletingKeys((prev) => new Set(prev).add(key))
    try {
      if (rule.scope === 'global') {
        await deleteGlobalRule(rule.name)
      } else {
        await deleteProjectRule(rule.projectId!, rule.name)
      }
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete rule')
    } finally {
      setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
    }
  }

  const handleApplyTemplate = async (template: RuleTemplate) => {
    setApplyingTemplate(template.id)
    try {
      if (templateScope === 'global') {
        await applyRuleTemplateGlobal(template.id)
      } else {
        await applyRuleTemplateProject(templateScope, template.id)
      }
      toast('success', `Applied "${template.name}" rule`)
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to apply template')
    } finally {
      setApplyingTemplate(null)
    }
  }

  const handleInitAll = async () => {
    setInitializing(true)
    try {
      await initAllRules()
      toast('success', 'Initialized rules directories for all projects')
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to initialize')
    } finally {
      setInitializing(false)
    }
  }

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <ShieldCheck className="w-6 h-6 text-green" />
            All Rules
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {rules?.length || 0} rules ({globalRules.length} global, {projectRules.length} project)
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowTemplates(!showTemplates)}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-surface border border-border text-text-secondary rounded-lg hover:bg-surface-2 transition-colors"
          >
            <BookTemplate className="w-4 h-4" />
            Templates
          </button>
          <button
            onClick={() => { setCreating(true); setCreateScope('global') }}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <Plus className="w-4 h-4" />
            New Rule
          </button>
        </div>
      </div>

      {/* Init Banner */}
      {projectsWithoutRules.length > 0 && (
        <div className="mb-6 bg-amber/5 border border-amber/20 rounded-xl p-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Zap className="w-5 h-5 text-amber" />
            <div>
              <p className="text-sm font-medium">{projectsWithoutRules.length} project{projectsWithoutRules.length > 1 ? 's' : ''} without rules directories</p>
              <p className="text-xs text-text-muted mt-0.5">
                {projectsWithoutRules.map(p => p.name).join(', ')}
              </p>
            </div>
          </div>
          <button
            onClick={handleInitAll}
            disabled={initializing}
            className="px-4 py-2 text-sm font-medium bg-amber/10 text-amber border border-amber/20 rounded-lg hover:bg-amber/20 disabled:opacity-40 transition-colors"
          >
            {initializing ? 'Initializing...' : 'Initialize All'}
          </button>
        </div>
      )}

      {/* Template Picker */}
      {showTemplates && (
        <div className="mb-6 bg-surface border border-accent/20 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <div>
              <p className="text-sm font-semibold">Rule Templates</p>
              <p className="text-xs text-text-muted mt-0.5">Pre-built rules you can apply instantly</p>
            </div>
            <div className="flex items-center gap-3">
              <select
                value={templateScope}
                onChange={(e) => setTemplateScope(e.target.value)}
                className="bg-surface-2 border border-border rounded-lg px-3 py-1.5 text-xs text-text-secondary focus:outline-none focus:border-accent/50"
              >
                <option value="global">Apply to: Global</option>
                {allProjects.map(p => (
                  <option key={p.id} value={p.id}>Apply to: {p.name}</option>
                ))}
              </select>
              <button onClick={() => setShowTemplates(false)} className="text-text-muted hover:text-text">
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            {(templates || []).map(t => (
              <div key={t.id} className="bg-surface-2 border border-border rounded-lg p-3 flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate">{t.name}</p>
                  <p className="text-xs text-text-muted mt-0.5">{t.description}</p>
                  <span className="inline-block mt-1.5 text-[10px] px-2 py-0.5 rounded-full bg-surface border border-border text-text-muted">{t.category}</span>
                </div>
                <button
                  onClick={() => handleApplyTemplate(t)}
                  disabled={applyingTemplate === t.id}
                  className="shrink-0 px-3 py-1.5 text-xs font-medium bg-accent/10 text-accent border border-accent/20 rounded-lg hover:bg-accent/20 disabled:opacity-40 transition-colors"
                >
                  {applyingTemplate === t.id ? '...' : 'Apply'}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search rules..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>
        <div className="flex items-center bg-surface border border-border rounded-lg p-0.5">
          {(['all', 'global', 'project'] as ScopeFilter[]).map(s => (
            <button
              key={s}
              onClick={() => setScopeFilter(s)}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                scopeFilter === s ? 'bg-accent text-white' : 'text-text-muted hover:text-text'
              }`}
            >
              {s === 'global' && <Globe className="w-3 h-3" />}
              {s === 'project' && <FolderOpen className="w-3 h-3" />}
              {s === 'all' && <Filter className="w-3 h-3" />}
              {s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>
        {uniqueProjects.length > 1 && scopeFilter !== 'global' && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
          >
            <option value="all">All projects</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        )}
      </div>

      {/* Create */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Rule</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="rule-name (e.g. no-console-log)"
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && !createLoading && handleCreate()}
            />
            <select
              value={createScope}
              onChange={(e) => setCreateScope(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              <option value="global">Global</option>
              {allProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              disabled={!newName.trim() || createLoading}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {createLoading ? 'Creating...' : 'Create'}
            </button>
          </div>
        </div>
      )}

      {/* Empty state */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <ShieldCheck className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No rules match your search' : 'No rules found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            Create rules or apply templates to define constraints Claude must follow
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global Rules Section */}
          {globalRules.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-blue-400" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalRules.length}
                </span>
                <span className="text-[10px] text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded-full">
                  All projects
                </span>
              </div>
              <div className="space-y-2">
                {globalRules.map((rule) => (
                  <RuleCard
                    key={`global-${rule.name}`}
                    rule={rule}
                    expanded={expanded}
                    setExpanded={setExpanded}
                    onDelete={handleDelete}
                    deleting={deletingKeys.has(`global-null-${rule.name}`)}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Project Rules Sections */}
          {[...projectGroups.entries()].map(([projectName, groupRules]) => {
            const projectId = groupRules[0]?.projectId
            return (
              <div key={projectName}>
                <div className="flex items-center gap-2 mb-3">
                  <FolderOpen className="w-4 h-4 text-green" />
                  <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                    {projectName}
                  </h2>
                  <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                    {groupRules.length}
                  </span>
                </div>
                <div className="space-y-2">
                  {groupRules.map((rule) => (
                    <RuleCard
                      key={`${projectId}-${rule.name}`}
                      rule={rule}
                      expanded={expanded}
                      setExpanded={setExpanded}
                      onDelete={handleDelete}
                      deleting={deletingKeys.has(`project-${projectId}-${rule.name}`)}
                    />
                  ))}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

function RuleCard({
  rule,
  expanded,
  setExpanded,
  onDelete,
  deleting,
}: {
  rule: UnifiedRule
  expanded: string | null
  setExpanded: (key: string | null) => void
  onDelete: (rule: UnifiedRule) => void
  deleting: boolean
}) {
  const key = `${rule.scope}-${rule.projectId}-${rule.name}`
  const isExpanded = expanded === key
  const editLink = rule.scope === 'global'
    ? `/global/rules/${rule.name}`
    : `/projects/${rule.projectId}/rules/${rule.name}`

  return (
    <div className="bg-surface border border-border rounded-xl overflow-hidden group">
      <div className="flex items-center justify-between px-4 py-3">
        <button
          onClick={() => setExpanded(isExpanded ? null : key)}
          className="flex items-center gap-3 flex-1 text-left"
        >
          {rule.scope === 'global'
            ? <Globe className="w-4 h-4 text-blue-400 shrink-0" />
            : <ShieldCheck className="w-4 h-4 text-green shrink-0" />
          }
          <span className="font-medium text-sm">{rule.name}</span>
          {isExpanded ? (
            <ChevronDown className="w-4 h-4 text-text-muted" />
          ) : (
            <ChevronRight className="w-4 h-4 text-text-muted" />
          )}
        </button>
        <div className="flex items-center gap-2">
          <span className="flex items-center gap-1 text-[11px] text-text-muted">
            <Clock className="w-3 h-3" />
            {new Date(rule.updatedAt).toLocaleDateString()}
          </span>
          <Link
            to={editLink}
            className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors opacity-0 group-hover:opacity-100"
          >
            <Pencil className="w-3.5 h-3.5" />
          </Link>
          <button
            onClick={() => onDelete(rule)}
            disabled={deleting}
            className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors opacity-0 group-hover:opacity-100"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
      {isExpanded && (
        <div className="border-t border-border p-4 bg-surface-2">
          <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap leading-relaxed">
            {rule.content}
          </pre>
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

